/**
 * 多 Agent 提示词与角色定义（按内容类型路由版本）。
 *
 * 这个文件会被 build-workflows.mjs 内联进：
 * - 分类与分块（生成 route 标记）
 * - 各分支的「构建请求」Code 节点
 * - 各分支的「解析结果」Code 节点
 *
 * 重要：不要在 schema 示例里要求模型输出 id；id 统一由聚合节点根据实体名生成，
 * 避免多个分块都输出 npc1 / scene1 导致应用侧按 id 合并时串实体。
 */

const STANDARD_SECTIONS = [
  "元信息", "真相与背景", "剧情梗概", "开场钩子", "关键NPC", "地点与场景",
  "线索", "遭遇与战斗", "道具与手书", "怪物与神话生物", "结局分支",
  "奖励与成长", "KP备注", "附录"
];

function routeLabel(route) {
  const labels = {
    narrative: "剧情与场景",
    npc: "NPC 与规则道具",
    notes: "设定笔记",
    handout: "线索与手书",
    setting: "设定与规则",
    image: "图片与地图",
    general: "综合提取",
    noop: "无需校验"
  };
  return labels[route] || String(route || "未知分支");
}

function sectionSchema() {
  const parts = [];
  for (const name of STANDARD_SECTIONS) parts.push("\"" + name + "\":\"...\"");
  return "{" + parts.join(",") + "}";
}

function imageSchemaHint() {
  return "{\"images\":[{\"filename\":\"与输入完全一致\",\"kind\":\"MAP / SCENE / HANDOUT / CLUE / NPC / ITEM / TEXT / OTHER\",\"transcription\":\"图中可见文字逐字抄录，最多 2000 字\",\"description\":\"客观描述画面，不要脑补\",\"section\":\"标准章节名\",\"sectionText\":\"可直接写入章节的中文正文，最多 1200 字\",\"scene\":null,\"clue\":null,\"npc\":null,\"item\":null}]}";
}

function npcSchema() {
  return "{\"aliases\":[],\"name\":\"NPC 名\",\"tier\":\"MINION / STANDARD / ELITE / BOSS\",\"rarity\":\"COMMON\",\"race\":null,\"tags\":[],\"description\":\"...\",\"portrait\":\"\",\"statText\":\"原文属性行 / 数值块逐字复制\",\"attributes\":{\"str\":50,\"con\":50,\"siz\":50,\"dex\":50,\"app\":50,\"int\":50,\"pow\":50,\"edu\":50,\"luck\":50},\"db\":\"1d4\",\"build\":1,\"move\":8,\"skills\":[{\"skill\":\"FIGHTING_BRAWL\",\"value\":40}],\"weapons\":[{\"name\":\"武器或攻击名\",\"damage\":\"1d3+db\",\"range\":\"MELEE\",\"skillId\":\"FIGHTING_BRAWL\",\"attacks\":1,\"notes\":\"\"}],\"maxHp\":12,\"maxMp\":10,\"maxSan\":50,\"maxDp\":0}";
}

function magicSchema() {
  return "{\"aliases\":[],\"name\":\"法术名\",\"skill\":\"OCCULT\",\"mpCost\":\"1\",\"sanCost\":\"0\",\"damage\":\"\",\"target\":\"ONE\",\"targeting\":\"ENEMY\",\"effects\":[{\"type\":\"DAMAGE\",\"amount\":\"1d6\"}],\"description\":\"...\"}";
}

function schemaHintForRoute(route) {
  if (route === "narrative") {
    return [
      "{\"meta\":{\"title\":\"...\",\"summary\":\"...\",\"background\":\"...\",\"occupationRecommendation\":\"...\"},",
      "\"sections\":" + sectionSchema() + ",",
      "\"structured\":{",
      "\"chapters\":[{\"aliases\":[],\"name\":\"章节名\",\"summary\":\"...\"}],",
      "\"scenes\":[{\"aliases\":[],\"name\":\"场景名\",\"description\":\"...\",\"width\":1600,\"height\":1000,\"gridType\":\"SQUARE\",\"bgColor\":\"#1a1a2e\",\"background\":\"\"}],",
      "\"clues\":[{\"aliases\":[],\"title\":\"线索名\",\"content\":\"...\",\"discoveryMethod\":\"...\",\"relatedNpc\":\"\",\"relatedPc\":\"\",\"linkedItemName\":\"\"}],",
      "\"encounters\":[{\"aliases\":[],\"name\":\"遭遇名\",\"sceneName\":\"场景名或留空\",\"chapterName\":\"章节名或留空\",\"trigger\":\"...\",\"setup\":{}}]",
      "}}"
    ].join("");
  }
  if (route === "npc") {
    return [
      "{\"structured\":{",
      "\"npcs\":[" + npcSchema() + "],",
      "\"items\":[{\"aliases\":[],\"name\":\"道具名\",\"itemType\":\"WEAPON / ITEM / TOME / ARTIFACT / EVIDENCE\",\"description\":\"...\",\"rarity\":\"COMMON\",\"image\":\"\",\"quantity\":1,\"damage\":\"\",\"range\":\"\",\"skillName\":\"\",\"accuracyMod\":0}],",
      "\"magic\":[" + magicSchema() + "],",
      "\"endings\":[{\"aliases\":[],\"name\":\"结局名\",\"condition\":\"...\",\"description\":\"...\"}],",
      "\"rewards\":[{\"aliases\":[],\"name\":\"奖励名\",\"description\":\"...\"}]",
      "}}"
    ].join("");
  }
  if (route === "handout") {
    return [
      "{\"meta\":{\"title\":\"...\",\"summary\":\"...\",\"background\":\"...\",\"occupationRecommendation\":\"\"},",
      "\"sections\":" + sectionSchema() + ",",
      "\"structured\":{",
      "\"scenes\":[{\"aliases\":[],\"name\":\"场景名\",\"description\":\"...\",\"width\":1600,\"height\":1000,\"gridType\":\"SQUARE\",\"bgColor\":\"#1a1a2e\",\"background\":\"\"}],",
      "\"clues\":[{\"aliases\":[],\"title\":\"线索名\",\"content\":\"...\",\"discoveryMethod\":\"...\",\"relatedNpc\":\"\",\"relatedPc\":\"\",\"linkedItemName\":\"\"}],",
      "\"items\":[{\"aliases\":[],\"name\":\"道具名\",\"itemType\":\"WEAPON / ITEM / TOME / ARTIFACT / EVIDENCE\",\"description\":\"...\",\"rarity\":\"COMMON\",\"image\":\"\",\"quantity\":1,\"damage\":\"\",\"range\":\"\",\"skillName\":\"\",\"accuracyMod\":0}],",
      "\"magic\":[" + magicSchema() + "]",
      "}}"
    ].join("");
  }
  if (route === "setting") {
    return [
      "{\"meta\":{\"title\":\"...\",\"summary\":\"...\",\"background\":\"...\",\"occupationRecommendation\":\"\"},",
      "\"sections\":" + sectionSchema() + ",",
      "\"structured\":{",
      "\"chapters\":[{\"aliases\":[],\"name\":\"章节名\",\"summary\":\"...\"}],",
      "\"scenes\":[{\"aliases\":[],\"name\":\"场景名\",\"description\":\"...\",\"width\":1600,\"height\":1000,\"gridType\":\"SQUARE\",\"bgColor\":\"#1a1a2e\",\"background\":\"\"}],",
      "\"npcs\":[" + npcSchema() + "],",
      "\"clues\":[{\"aliases\":[],\"title\":\"线索名\",\"content\":\"...\",\"discoveryMethod\":\"...\",\"relatedNpc\":\"\",\"relatedPc\":\"\",\"linkedItemName\":\"\"}],",
      "\"items\":[{\"aliases\":[],\"name\":\"道具名\",\"itemType\":\"ITEM\",\"description\":\"...\",\"rarity\":\"COMMON\",\"image\":\"\",\"quantity\":1}],",
      "\"magic\":[" + magicSchema() + "],",
      "\"endings\":[{\"aliases\":[],\"name\":\"结局名\",\"condition\":\"...\",\"description\":\"...\"}],",
      "\"rewards\":[{\"aliases\":[],\"name\":\"奖励名\",\"description\":\"...\"}]",
      "}}"
    ].join("");
  }
  if (route === "notes") {
    return "{\"meta\":{\"title\":\"...\",\"summary\":\"...\",\"background\":\"...\",\"occupationRecommendation\":\"...\"},\"sections\":" + sectionSchema() + "}";
  }
  if (route === "image") return imageSchemaHint();
  // general
  return [
    "{\"meta\":{\"title\":\"...\",\"summary\":\"...\",\"background\":\"...\",\"occupationRecommendation\":\"\"},",
    "\"sections\":" + sectionSchema() + ",",
    "\"structured\":{",
    "\"chapters\":[{\"aliases\":[],\"name\":\"章节名\",\"summary\":\"...\"}],",
    "\"scenes\":[{\"aliases\":[],\"name\":\"场景名\",\"description\":\"...\"}],",
    "\"encounters\":[{\"aliases\":[],\"name\":\"遭遇名\",\"sceneName\":\"\",\"chapterName\":\"\",\"trigger\":\"...\",\"setup\":{}}],",
    "\"npcs\":[" + npcSchema() + "],",
    "\"clues\":[{\"aliases\":[],\"title\":\"线索名\",\"content\":\"...\",\"discoveryMethod\":\"...\",\"linkedItemName\":\"\"}],",
    "\"items\":[{\"aliases\":[],\"name\":\"道具名\",\"itemType\":\"ITEM\",\"description\":\"...\"}],",
    "\"magic\":[" + magicSchema() + "],",
    "\"endings\":[{\"aliases\":[],\"name\":\"结局名\",\"condition\":\"...\",\"description\":\"...\"}],",
    "\"rewards\":[{\"aliases\":[],\"name\":\"奖励名\",\"description\":\"...\"}]",
    "}}"
  ].join("");
}

function agentSystemPrompt(route, hints, opts) {
  const lines = [];
  lines.push("你是严谨的中文 TRPG 团本解析 Agent，当前分支身份：" + routeLabel(route) + "。");
  lines.push("目标系统：" + hints.system + "；年代：" + hints.era + "。");
  if (opts && opts.retry) lines.push("本次是上一次截断或失败后的压缩重试调用。");
  lines.push("只依据用户消息中的素材片段输出严格 JSON；不要续写、不要解释、不要输出思维过程或 markdown。");
  lines.push("输出必须是单个合法 JSON 对象，并且必须完整闭合。");
  return lines.join("\n");
}

function agentCommonRequirements(route, hints, opts) {
  const lines = [];
  lines.push("当前分支只负责：" + routeLabel(route) + "。不要输出本分支之外的结构。");
  lines.push("只处理下面这一小段素材，不要参考其他段落或历史任务。");
  if (hints.instructions && String(hints.instructions).trim().length > 0) {
    lines.push("用户额外要求：" + String(hints.instructions).trim().slice(0, 2000));
  }
  lines.push("没有在原文明确定出现的字段直接省略；禁止编造、禁止用示例值补全。");
  lines.push("标题、编号、专有名词、数字、判定值必须与原文完全一致；NPC 数值必须逐字保留在 statText。");
  lines.push("禁止输出 id 字段；id 由系统根据名称自动生成。sceneId / chapterId / linkedItemId 等引用字段请填对应名称，不要填机器 id。");
  lines.push("只输出一个合法 JSON 对象，不要 markdown 代码围栏，不要解释；JSON 必须完整闭合。");
  lines.push("严格去重与收敛：");
  lines.push("- 只有原文出现明确的『场景 N: / 第 N 章: / 地图节点』或独立地点标题时才输出 scene；房间、走廊、楼层、事件、NPC 都不算新场景，同一分块最多 1 个新场景。");
  lines.push("- 每个分块独立处理：如果本段出现上述明确的场景 / 地点标题，structured.scenes 必须至少输出 1 条，不要因为可能与其他分块重复而省略；重复由系统统一去重。");
  lines.push("- 如果原文只提到某个文字材料的标题、页码、页眉，或只指向一张图片而没有正文，不要生成空的 / 占位的 clue，交给图片分析分支处理。");
  lines.push("- 如果原文出现 # / ## 级章节标题或明确章节名，必须放入 structured.chapters；chapter 与 scene 可以同时存在，不要因为输出了 scene 就省略 chapters。");
  lines.push("- clues 只提取会影响调查推进、提供新信息或可交给玩家的内容；每个分块最多 2 条；普通背景、氛围描述、NPC 生平请归入 sections，不要单独列为 clue。");
  lines.push("- 同一实体的不同称呼 / 化名统一放进 aliases；name / title 用原文最正式的名称，不要按称呼拆成多条。");
  lines.push("- items 只提取可携带 / 可使用的实体道具、书籍、武器、神器；文字材料、线索、档案、笔记本身请放入 clues，不要放入 items。");
  lines.push("- magic 只提取原文明确写出的法术 / 咒文；同一法术的不同译名请合并为一条。");

  lines.push("- NPC 的 skills 必须使用规则包技能 ID，不要输出中文技能名或描述性技能名。常用 ID：FIGHTING_BRAWL(格斗/斗殴/肉搏/爪/牙/撕咬)、DODGE(闪避)、FIREARMS_HANDGUN(手枪)、FIREARMS_RIFLE(步枪/霰弹枪)、FIREARMS_BOW(弓)、THROW(投掷)、CLIMB(攀爬)、STEALTH(潜行)、LISTEN(聆听)、SPOT_HIDDEN(侦查)、SLEIGHT_OF_HAND(妙手)、LIBRARY_USE(图书馆使用)、OCCULT(神秘学)、CTHULHU_MYTHOS(克苏鲁神话)、LAW(法律)、FIRST_AID(急救)、PSYCHOLOGY(心理学)、CHARM(魅惑)、FAST_TALK(话术)、INTIMIDATE(恐吓)、PERSUADE(说服)、CREDIT_RATING(信用评级)。技能条目格式：{\"skill\":\"FIGHTING_BRAWL\",\"value\":40}。");
  lines.push("- NPC 的 weapons 必须可结算：{\"name\":\"武器或攻击名\",\"damage\":\"1d3+db 或 1d6 等纯骰式\",\"range\":\"MELEE / NEAR / FAR\",\"skillId\":\"FIGHTING_BRAWL\",\"attacks\":1,\"notes\":\"\"}；不要写中文伤害描述，没有武器就省略。");
  lines.push("- 法术 effects 必须是可执行对象数组，不要写字符串。可用 type：DAMAGE(amount 骰式)、HEAL(amount 骰式)、MP_RESTORE(amount 数字)、MP_DRAIN(amount 数字)、SAN_LOSS(amount 骰式)、SAN_RESTORE(amount 数字)、STATUS(key,stacks)、ARMOR(amount 骰式,durationTicks=0)、SUMMON(name,count,durationTicks=0)、DOT(amount 骰式,durationTicks)、STUN(durationActions)、CONTROL(durationActions)、CLEANSE(keys)。mpCost 必须是数字或公式字符串；sanCost 必须是骰式或数字；没有直接战斗效果的法术 effects 可以为空，不要编造。");
  lines.push("- 给护甲 / 防护物理伤害的法术写 ARMOR，不要写成 DAMAGE；召唤类法术写 SUMMON，name 填召唤物名，count 填数量；召唤物会优先匹配房间内独立 NPC 卡。");
  lines.push("- 如果原文明确写出结局 / 奖励 / SAN 成长 / 技能成长 / 酬金等，必须放入对应字段，不要遗漏。");
  lines.push("尽量短：sections 只写一句话摘要，structured 每个数组最多 2 条，description 压缩到一句话。");
  if (opts && opts.retry) {
    lines.push("这是截断/失败后的重试，请进一步压缩：只保留最重要的 1-3 条记录，总长度控制在 800 个中文字符以内，并务必闭合 JSON。");
  }
  return lines;
}

function agentUserPrompt(route, chunk, hints, opts) {
  const lines = agentCommonRequirements(route, hints, opts);
  lines.push("来源：" + String(chunk.filename || "素材") + "，本文件第 " + String(chunk.fileIndex || 1) + "/" + String(chunk.fileTotal || 1) + " 段" + (chunk.heading ? "，最近标题：" + chunk.heading : ""));
  if (opts && opts.splitIndex !== undefined && opts.splitTotal !== undefined) {
    lines.push("这是原失败片段的第 " + String(opts.splitIndex + 1) + "/" + String(opts.splitTotal) + " 部分，只提取本部分内容。");
  }
  lines.push("只允许输出以下结构（示例值只是格式说明，不是素材内容；不要输出 id 字段）：");
  lines.push(schemaHintForRoute(route));
  lines.push("");
  lines.push("本段原文：");
  lines.push(String(chunk.text || ""));
  return lines.join("\n");
}

function buildAgentMessages(route, chunk, hints, opts) {
  return [
    { role: "system", content: agentSystemPrompt(route, hints, opts) },
    { role: "user", content: agentUserPrompt(route, chunk, hints, opts) }
  ];
}

function buildVisionMessages(batch, hints) {
  const lines = [];
  lines.push("你是图片视觉分析 Agent（分支身份：" + routeLabel("image") + "）。");
  lines.push("目标系统：" + hints.system + "；年代：" + hints.era + "。");
  lines.push("请逐张分析下面的图片素材，并把结果整理成单个合法 JSON 对象：{\"images\":[...]}。");
  lines.push("每张图片必须返回一条 images 记录，filename 与输入完全一致。");
  lines.push("kind 只能是 MAP / SCENE / HANDOUT / CLUE / NPC / ITEM / TEXT / OTHER 之一。");
  lines.push("transcription 逐字抄录图中可见文字（最多 2000 字）；description 只客观描述画面，不要脑补。");
  lines.push("section 选一个标准章节；sectionText 可直接写进该章节的中文正文，最多 1200 字。");
  lines.push("如果是地图尽量给出 scene；是手书/文件给 clue；是人物立绘给 npc；是物品给 item；否则对应字段返回 null。");
  lines.push("只返回单个合法 JSON 对象，不要解释、不要 markdown 代码围栏，数组最多 " + String(batch.length) + " 条。");
  lines.push("");
  lines.push("图片清单：");
  for (const image of batch) {
    lines.push("- filename：" + String(image.filename || "") + "；引用路径：" + String(image.relativePath || ""));
    if (image.pageNumber !== undefined && image.pageNumber !== null) {
      lines.push("  来源：PDF 第 " + String(image.pageNumber) + " 页" + (image.origin === "PAGE_RENDER" ? "（整页渲染）" : "（内嵌图）"));
    }
    if (image.pageText !== undefined && String(image.pageText).trim().length > 0) {
      lines.push("  同页文字（可能不完整）：" + String(image.pageText).trim().slice(0, 1200));
    }
  }
  const userContent = [{ type: "text", text: lines.join("\n") }];
  for (const image of batch) {
    if (image && typeof image.dataUrl === "string" && image.dataUrl.length > 0) {
      userContent.push({ type: "image_url", image_url: { url: image.dataUrl } });
    }
  }
  return [
    { role: "system", content: "你是 TRPG 素材视觉分析助手。每次调用都是独立任务，只依据当前图片与随图文字输出严格 JSON；看不清或不确定的内容必须如实说明，不得脑补。" },
    { role: "user", content: userContent }
  ];
}

function validatorSystemPrompt() {
  return [
    "你是严格的 JSON 格式校验与修复 Agent。",
    "你的唯一职责是把用户提供的模型原始输出修复为单个合法 JSON 对象。",
    "禁止新增、删除或编造事实；只允许调整格式、补齐括号、去掉解释文字、合并重复顶层对象、丢弃不完整字段。",
    "输出必须是可直接 JSON.parse 的单个对象，不要 markdown，不要解释。",
    "不要输出 id 字段；id 由系统根据名称自动生成。"
  ].join("");
}

function validatorUserPrompt(rawContent, route, label) {
  const lines = [];
  lines.push("来源标签：" + String(label || "未命名"));
  lines.push("原始分支：" + routeLabel(route));
  lines.push("期望字段形状（只作为校验参考，不要照抄示例值）：");
  lines.push(schemaHintForRoute(route));
  lines.push("要求：");
  lines.push("1) 如果原文里有多个 JSON 对象，选择字段最完整的一个，不要拼接无关内容。");
  lines.push("2) 如果 JSON 被截断，只保留已经完整闭合的字段，丢弃未完成部分，输出合法 JSON。");
  lines.push("3) 如果原文夹杂解释文字，删除解释文字，只保留 JSON。");
  lines.push("4) 不要新增原文没有的事实，不要输出 id。");
  lines.push("");
  lines.push("原始输出：");
  lines.push(String(rawContent || ""));
  return lines.join("\n");
}

function buildValidatorMessages(rawContent, route, label) {
  return [
    { role: "system", content: validatorSystemPrompt() },
    { role: "user", content: validatorUserPrompt(rawContent, route, label) }
  ];
}

/**
 * n8n 团本解析工作流：内容分类与分块。
 *
 * 这个节点只负责：
 * - 读取 webhook 输入；
 * - 按文件内容特征判断文档类型；
 * - 按场景边界切分为小段；
 * - 为每个分块决定 1-2 个内容分支（route）；
 * - 输出 route 标记，交给 Switch 选择器分流。
 *
 * 最终请求体由各分支的「构建请求」节点生成，这里不调用模型。
 */

const rawInput = (items && items[0] && items[0].json) ? items[0].json : {};
const input = (rawInput && rawInput.body && typeof rawInput.body === "object") ? rawInput.body : rawInput;
const env = (typeof $env === "object" && $env !== null) ? $env : {};
const deepseekBaseUrl = String((env.DEEPSEEK_BASE_URL || "https://api.deepseek.com")).replace(/\/+$/, "");
const model = String(input.model || env.DEEPSEEK_MODEL || "deepseek-flash").trim() || "deepseek-flash";
const visionModel = String(input.visionModel || model).trim() || model;
const configuredMaxTokens = Number(env.DEEPSEEK_MAX_TOKENS || 8192);
const maxTokens = Number.isFinite(configuredMaxTokens) && configuredMaxTokens > 0 ? Math.floor(configuredMaxTokens) : 8192;
const hints = {
  system: input.system === "TOUHOU" ? "TOUHOU" : "COC7",
  era: String(input.era || "MODERN"),
  instructions: String(input.instructions || "")
};
const context = { model, visionModel, maxTokens, deepseekBaseUrl, hints };
const sources = Array.isArray(input.sources) && input.sources.length > 0
  ? input.sources
  : (Array.isArray(input.chunks) ? input.chunks.map((chunk) => ({ filename: chunk.filename, text: chunk.text })) : []);
const images = Array.isArray(input.images) ? input.images : [];
const output = [];

function extensionOf(filename) {
  const match = /[.]([a-z0-9]+)$/i.exec(String(filename || ""));
  return match && match[1] ? match[1].toLowerCase() : "";
}

function contentScores(text) {
  const value = String(text || "");
  const statHits = (value.match(/(?:STR|CON|SIZ|DEX|APP|INT|POW|EDU|LUCK|HP|MP|SAN|DP|DB|Build|Move|力量|体质|体型|敏捷|外貌|智力|意志|教育|幸运|生命值|魔法值|理智值|耐久|伤害加值|体格|移动)/gi) || []).length;
  const narrativeHits = (value.match(/(场景|章节|第\s*[一二三四五六七八九十百0-9]+\s*[章幕节]|调查员|剧情|背景|遭遇|钩子|结局)/g) || []).length;
  const clueHits = (value.match(/(线索|手书|笔记|日记|信件|记录|档案|资料|证物)/g) || []).length;
  const itemMagicHits = (value.match(/(道具|物品|法术|魔法|咒文|魔导书|仪式|武器|装备|宝物|神器)/g) || []).length;
  const settingHits = (value.match(/(设定|规则|附录|背景|历史|地理|组织|参考|说明|时间线|年表)/g) || []).length;
  const sceneHeadings = (value.match(/^(#{1,6}\s*)?(场景|第\s*[一二三四五六七八九十百0-9]+\s*[幕章节]|chapter|act\b)/gim) || []).length;
  const commentaryHits = (value.match(/(相比|为什么不|能否|能不能|是否|建议|如果|问题|新手|KP|玩家|此模组|本模组|改进|调整|设计)/gi) || []).length;
  const endingHits = (value.match(/(结局|结尾|收尾|最终|胜利|失败|存活|死亡|逃出|解决)/g) || []).length;
  const rewardHits = (value.match(/(奖励|成长|报酬|酬金|SAN\s*值|理智值|技能成长|恢复)/gi) || []).length;
  return { statHits, narrativeHits, clueHits, itemMagicHits, settingHits, sceneHeadings, commentaryHits, endingHits, rewardHits };
}

function classifySource(source) {
  const filename = String(source && source.filename ? source.filename : "material");
  const lower = filename.toLowerCase();
  const extension = extensionOf(filename);
  const text = String(source && source.text ? source.text : "");
  const scores = contentScores(text);

  if (["csv", "tsv", "xlsx", "xls", "json", "yaml", "yml"].includes(extension)) return "NPC_SHEET";
  if (/(npc|npc数据|stat|数据表|属性表|数值表|怪物表|bestiary|monster)/i.test(lower)) return "NPC_SHEET";
  if (/(手书|线索|handout|clue|玩家材料)/i.test(lower)) return "HANDOUT";
  if (/(设定|规则|附录|参考资料|reference|rules?|setting|appendix)/i.test(lower)) return "SETTING";

  const density = text.length > 0 ? scores.statHits / Math.max(1, text.length / 1000) : 0;
  if (text.length > 0 && text.length <= 3500 && scores.sceneHeadings === 0 && scores.statHits < 2 && scores.commentaryHits >= 4) return "COMMENTARY";
  if (text.length > 0 && text.length <= 4000 && scores.statHits >= 12 && density >= 5 && scores.narrativeHits <= 3) return "NPC_SHEET";
  if (text.length > 0 && text.length <= 2500 && scores.statHits < 2 && scores.clueHits + scores.itemMagicHits >= 2) return "HANDOUT";
  return "MODULE";
}

function chooseRoutes(docType, chunk) {
  const text = String(chunk && chunk.text ? chunk.text : "");
  const scores = contentScores(text);
  if (docType === "NPC_SHEET") return ["npc"];
  if (docType === "COMMENTARY") return ["notes"];
  if (docType === "HANDOUT") return ["handout"];
  if (docType === "SETTING") {
    if (scores.statHits >= 4 && scores.narrativeHits <= 1) return ["npc"];
    return ["setting"];
  }

  const routes = [];
  const narrativeCue = scores.narrativeHits >= 1 || scores.sceneHeadings >= 1 || text.length > 900;
  const structuredCue = scores.statHits >= 2 || scores.itemMagicHits >= 1 || scores.endingHits >= 1 || scores.rewardHits >= 1;
  const handoutCue = scores.clueHits + scores.itemMagicHits >= 2;

  if (narrativeCue) routes.push("narrative");
  if (structuredCue) routes.push("npc");
  if (handoutCue && routes.length === 0) routes.push("handout");
  if (routes.length === 0) routes.push("general");
  return Array.from(new Set(routes)).slice(0, 2);
}

function isSceneBoundary(text) {
  const firstLine = String(text || "").split("\n")[0].trim();
  if (firstLine.length === 0) return false;
  if (/^(#{1,6}\s*)?(场景|第\s*[一二三四五六七八九十百0-9]+\s*[幕章节]|chapter|act\b)/i.test(firstLine)) return true;
  if (/^[-=—]{3,}$/.test(firstLine)) return true;
  if (/^\[\d{1,2}:\d{2}(?::\d{2})?\]/.test(firstLine)) return true;
  if (/^【[^】]*(场景|第\s*[一二三四五六七八九十百0-9]+\s*[幕章节])[^】]*】/.test(firstLine)) return true;
  return false;
}

function chunkSourceByScene(filename, rawText) {
  const target = 3000;
  const max = 4200;
  const normalized = String(rawText || "").replace(/\r\n?/g, "\n").trim();
  if (normalized.length === 0) return [];

  const paragraphs = [];
  let heading = "";
  for (const block of normalized.split(/\n{2,}/)) {
    const text = block.trim();
    if (text.length === 0) continue;
    const firstLine = text.split("\n")[0].trim();
    if (/^(#{1,6}\s+|【[^】]{1,40}】\s*$)/.test(firstLine)) {
      heading = firstLine.replace(/^#{1,6}\s+/, "").replace(/^【|】$/g, "").trim() || heading;
    }
    paragraphs.push({ text, heading });
  }
  if (paragraphs.length === 0) paragraphs.push({ text: normalized, heading });

  const expanded = [];
  for (const paragraph of paragraphs) {
    if (paragraph.text.length <= max) {
      expanded.push(paragraph);
      continue;
    }
    const pieces = paragraph.text.split(/(?<=[。！？!?；;])\s*/).filter((piece) => piece.trim().length > 0);
    let buffer = "";
    const flush = () => {
      if (buffer.trim().length > 0) expanded.push({ text: buffer.trim(), heading: paragraph.heading });
      buffer = "";
    };
    for (const piece of pieces) {
      if (piece.length > max) {
        flush();
        for (let offset = 0; offset < piece.length; offset += target) {
          expanded.push({ text: piece.slice(offset, offset + target), heading: paragraph.heading });
        }
        continue;
      }
      if (buffer.length + piece.length > target) flush();
      buffer += piece;
    }
    flush();
  }

  const chunks = [];
  let buffer = "";
  let bufferHeading = expanded[0] ? expanded[0].heading : "";
  let forceHeading = "";
  const pushChunk = () => {
    const text = buffer.trim();
    if (text.length === 0) return;
    chunks.push({ text, heading: forceHeading || bufferHeading, charCount: text.length });
    buffer = "";
  };

  for (const paragraph of expanded) {
    const startsScene = isSceneBoundary(paragraph.text);
    if (buffer.length > 0 && startsScene) pushChunk();
    if (buffer.length === 0) {
      bufferHeading = paragraph.heading;
      forceHeading = paragraph.heading;
    } else if (paragraph.heading.length > 0 && paragraph.heading !== bufferHeading) {
      if (buffer.length >= 1000) pushChunk();
      forceHeading = paragraph.heading;
    }
    if (buffer.length > 0 && buffer.length + paragraph.text.length + 2 > target) pushChunk();
    if (buffer.length > 0) buffer += "\n\n";
    buffer += paragraph.text;
    if (buffer.length >= target) pushChunk();
  }
  pushChunk();

  return chunks.map((chunk, index) => ({
    filename,
    fileIndex: index + 1,
    fileTotal: chunks.length,
    heading: chunk.heading,
    text: chunk.text,
    charCount: chunk.charCount
  }));
}

for (const source of sources) {
  const filename = String(source && source.filename ? source.filename : "material");
  const docType = classifySource(source);
  const chunks = chunkSourceByScene(filename, source ? source.text : "");
  for (const chunk of chunks) {
    const routes = chooseRoutes(docType, chunk);
    const chunkGroupId = "text:" + filename + ":" + String(chunk.fileIndex) + "/" + String(chunk.fileTotal);
    for (const route of routes) {
      output.push({
        json: {
          route,
          docType,
          kind: "chunk",
          chunk,
          chunkGroupId,
          originId: chunkGroupId + ":" + route,
          label: "场景段 " + filename + " " + String(chunk.fileIndex) + "/" + String(chunk.fileTotal) + " · " + routeLabel(route),
          context
        }
      });
    }
  }
}

const batchSize = 2;
for (let offset = 0; offset < images.length; offset += batchSize) {
  const batch = images.slice(offset, offset + batchSize);
  const chunkGroupId = "image:" + String(offset / batchSize + 1);
  output.push({
    json: {
      route: "image",
      docType: "IMAGE",
      kind: "image",
      imageBatch: batch.map((image) => ({
        filename: image.filename,
        relativePath: image.relativePath,
        mime: image.mime,
        dataUrl: image.dataUrl,
        pageNumber: image.pageNumber,
        pageText: image.pageText,
        origin: image.origin
      })),
      chunkGroupId,
      originId: chunkGroupId + ":image",
      label: "图片分析 " + batch.map((image) => image.filename).join("、").slice(0, 80),
      context
    }
  });
}

return output;

/**
 * 多 Agent 提示词与角色定义（按内容类型路由版本）。
 *
 * 这个文件会被 build-workflows.mjs 内联进：
 * - 分类与分块（生成 route 标记）
 * - 各分支的「构建请求」Code 节点
 * - 各分支的「解析结果」Code 节点
 *
 * 重要：不要在 schema 示例里要求模型输出 id；id 统一由聚合节点根据实体名生成，
 * 避免多个分块都输出 npc1 / scene1 导致应用侧按 id 合并时串实体。
 */

const STANDARD_SECTIONS = [
  "元信息", "真相与背景", "剧情梗概", "开场钩子", "关键NPC", "地点与场景",
  "线索", "遭遇与战斗", "道具与手书", "怪物与神话生物", "结局分支",
  "奖励与成长", "KP备注", "附录"
];

function routeLabel(route) {
  const labels = {
    narrative: "剧情与场景",
    npc: "NPC 与规则道具",
    notes: "设定笔记",
    handout: "线索与手书",
    setting: "设定与规则",
    image: "图片与地图",
    general: "综合提取",
    noop: "无需校验"
  };
  return labels[route] || String(route || "未知分支");
}

function sectionSchema() {
  const parts = [];
  for (const name of STANDARD_SECTIONS) parts.push("\"" + name + "\":\"...\"");
  return "{" + parts.join(",") + "}";
}

function imageSchemaHint() {
  return "{\"images\":[{\"filename\":\"与输入完全一致\",\"kind\":\"MAP / SCENE / HANDOUT / CLUE / NPC / ITEM / TEXT / OTHER\",\"transcription\":\"图中可见文字逐字抄录，最多 2000 字\",\"description\":\"客观描述画面，不要脑补\",\"section\":\"标准章节名\",\"sectionText\":\"可直接写入章节的中文正文，最多 1200 字\",\"scene\":null,\"clue\":null,\"npc\":null,\"item\":null}]}";
}

function npcSchema() {
  return "{\"aliases\":[],\"name\":\"NPC 名\",\"tier\":\"MINION / STANDARD / ELITE / BOSS\",\"rarity\":\"COMMON\",\"race\":null,\"tags\":[],\"description\":\"...\",\"portrait\":\"\",\"statText\":\"原文属性行 / 数值块逐字复制\",\"attributes\":{\"str\":50,\"con\":50,\"siz\":50,\"dex\":50,\"app\":50,\"int\":50,\"pow\":50,\"edu\":50,\"luck\":50},\"db\":\"1d4\",\"build\":1,\"move\":8,\"skills\":[{\"skill\":\"FIGHTING_BRAWL\",\"value\":40}],\"weapons\":[{\"name\":\"武器或攻击名\",\"damage\":\"1d3+db\",\"range\":\"MELEE\",\"skillId\":\"FIGHTING_BRAWL\",\"attacks\":1,\"notes\":\"\"}],\"maxHp\":12,\"maxMp\":10,\"maxSan\":50,\"maxDp\":0}";
}

function magicSchema() {
  return "{\"aliases\":[],\"name\":\"法术名\",\"skill\":\"OCCULT\",\"mpCost\":\"1\",\"sanCost\":\"0\",\"damage\":\"\",\"target\":\"ONE\",\"targeting\":\"ENEMY\",\"effects\":[{\"type\":\"DAMAGE\",\"amount\":\"1d6\"}],\"description\":\"...\"}";
}

function schemaHintForRoute(route) {
  if (route === "narrative") {
    return [
      "{\"meta\":{\"title\":\"...\",\"summary\":\"...\",\"background\":\"...\",\"occupationRecommendation\":\"...\"},",
      "\"sections\":" + sectionSchema() + ",",
      "\"structured\":{",
      "\"chapters\":[{\"aliases\":[],\"name\":\"章节名\",\"summary\":\"...\"}],",
      "\"scenes\":[{\"aliases\":[],\"name\":\"场景名\",\"description\":\"...\",\"width\":1600,\"height\":1000,\"gridType\":\"SQUARE\",\"bgColor\":\"#1a1a2e\",\"background\":\"\"}],",
      "\"clues\":[{\"aliases\":[],\"title\":\"线索名\",\"content\":\"...\",\"discoveryMethod\":\"...\",\"relatedNpc\":\"\",\"relatedPc\":\"\",\"linkedItemName\":\"\"}],",
      "\"encounters\":[{\"aliases\":[],\"name\":\"遭遇名\",\"sceneName\":\"场景名或留空\",\"chapterName\":\"章节名或留空\",\"trigger\":\"...\",\"setup\":{}}]",
      "}}"
    ].join("");
  }
  if (route === "npc") {
    return [
      "{\"structured\":{",
      "\"npcs\":[" + npcSchema() + "],",
      "\"items\":[{\"aliases\":[],\"name\":\"道具名\",\"itemType\":\"WEAPON / ITEM / TOME / ARTIFACT / EVIDENCE\",\"description\":\"...\",\"rarity\":\"COMMON\",\"image\":\"\",\"quantity\":1,\"damage\":\"\",\"range\":\"\",\"skillName\":\"\",\"accuracyMod\":0}],",
      "\"magic\":[" + magicSchema() + "],",
      "\"endings\":[{\"aliases\":[],\"name\":\"结局名\",\"condition\":\"...\",\"description\":\"...\"}],",
      "\"rewards\":[{\"aliases\":[],\"name\":\"奖励名\",\"description\":\"...\"}]",
      "}}"
    ].join("");
  }
  if (route === "handout") {
    return [
      "{\"meta\":{\"title\":\"...\",\"summary\":\"...\",\"background\":\"...\",\"occupationRecommendation\":\"\"},",
      "\"sections\":" + sectionSchema() + ",",
      "\"structured\":{",
      "\"scenes\":[{\"aliases\":[],\"name\":\"场景名\",\"description\":\"...\",\"width\":1600,\"height\":1000,\"gridType\":\"SQUARE\",\"bgColor\":\"#1a1a2e\",\"background\":\"\"}],",
      "\"clues\":[{\"aliases\":[],\"title\":\"线索名\",\"content\":\"...\",\"discoveryMethod\":\"...\",\"relatedNpc\":\"\",\"relatedPc\":\"\",\"linkedItemName\":\"\"}],",
      "\"items\":[{\"aliases\":[],\"name\":\"道具名\",\"itemType\":\"WEAPON / ITEM / TOME / ARTIFACT / EVIDENCE\",\"description\":\"...\",\"rarity\":\"COMMON\",\"image\":\"\",\"quantity\":1,\"damage\":\"\",\"range\":\"\",\"skillName\":\"\",\"accuracyMod\":0}],",
      "\"magic\":[" + magicSchema() + "]",
      "}}"
    ].join("");
  }
  if (route === "setting") {
    return [
      "{\"meta\":{\"title\":\"...\",\"summary\":\"...\",\"background\":\"...\",\"occupationRecommendation\":\"\"},",
      "\"sections\":" + sectionSchema() + ",",
      "\"structured\":{",
      "\"chapters\":[{\"aliases\":[],\"name\":\"章节名\",\"summary\":\"...\"}],",
      "\"scenes\":[{\"aliases\":[],\"name\":\"场景名\",\"description\":\"...\",\"width\":1600,\"height\":1000,\"gridType\":\"SQUARE\",\"bgColor\":\"#1a1a2e\",\"background\":\"\"}],",
      "\"npcs\":[" + npcSchema() + "],",
      "\"clues\":[{\"aliases\":[],\"title\":\"线索名\",\"content\":\"...\",\"discoveryMethod\":\"...\",\"relatedNpc\":\"\",\"relatedPc\":\"\",\"linkedItemName\":\"\"}],",
      "\"items\":[{\"aliases\":[],\"name\":\"道具名\",\"itemType\":\"ITEM\",\"description\":\"...\",\"rarity\":\"COMMON\",\"image\":\"\",\"quantity\":1}],",
      "\"magic\":[" + magicSchema() + "],",
      "\"endings\":[{\"aliases\":[],\"name\":\"结局名\",\"condition\":\"...\",\"description\":\"...\"}],",
      "\"rewards\":[{\"aliases\":[],\"name\":\"奖励名\",\"description\":\"...\"}]",
      "}}"
    ].join("");
  }
  if (route === "notes") {
    return "{\"meta\":{\"title\":\"...\",\"summary\":\"...\",\"background\":\"...\",\"occupationRecommendation\":\"...\"},\"sections\":" + sectionSchema() + "}";
  }
  if (route === "image") return imageSchemaHint();
  // general
  return [
    "{\"meta\":{\"title\":\"...\",\"summary\":\"...\",\"background\":\"...\",\"occupationRecommendation\":\"\"},",
    "\"sections\":" + sectionSchema() + ",",
    "\"structured\":{",
    "\"chapters\":[{\"aliases\":[],\"name\":\"章节名\",\"summary\":\"...\"}],",
    "\"scenes\":[{\"aliases\":[],\"name\":\"场景名\",\"description\":\"...\"}],",
    "\"encounters\":[{\"aliases\":[],\"name\":\"遭遇名\",\"sceneName\":\"\",\"chapterName\":\"\",\"trigger\":\"...\",\"setup\":{}}],",
    "\"npcs\":[" + npcSchema() + "],",
    "\"clues\":[{\"aliases\":[],\"title\":\"线索名\",\"content\":\"...\",\"discoveryMethod\":\"...\",\"linkedItemName\":\"\"}],",
    "\"items\":[{\"aliases\":[],\"name\":\"道具名\",\"itemType\":\"ITEM\",\"description\":\"...\"}],",
    "\"magic\":[" + magicSchema() + "],",
    "\"endings\":[{\"aliases\":[],\"name\":\"结局名\",\"condition\":\"...\",\"description\":\"...\"}],",
    "\"rewards\":[{\"aliases\":[],\"name\":\"奖励名\",\"description\":\"...\"}]",
    "}}"
  ].join("");
}

function agentSystemPrompt(route, hints, opts) {
  const lines = [];
  lines.push("你是严谨的中文 TRPG 团本解析 Agent，当前分支身份：" + routeLabel(route) + "。");
  lines.push("目标系统：" + hints.system + "；年代：" + hints.era + "。");
  if (opts && opts.retry) lines.push("本次是上一次截断或失败后的压缩重试调用。");
  lines.push("只依据用户消息中的素材片段输出严格 JSON；不要续写、不要解释、不要输出思维过程或 markdown。");
  lines.push("输出必须是单个合法 JSON 对象，并且必须完整闭合。");
  return lines.join("\n");
}

function agentCommonRequirements(route, hints, opts) {
  const lines = [];
  lines.push("当前分支只负责：" + routeLabel(route) + "。不要输出本分支之外的结构。");
  lines.push("只处理下面这一小段素材，不要参考其他段落或历史任务。");
  if (hints.instructions && String(hints.instructions).trim().length > 0) {
    lines.push("用户额外要求：" + String(hints.instructions).trim().slice(0, 2000));
  }
  lines.push("没有在原文明确定出现的字段直接省略；禁止编造、禁止用示例值补全。");
  lines.push("标题、编号、专有名词、数字、判定值必须与原文完全一致；NPC 数值必须逐字保留在 statText。");
  lines.push("禁止输出 id 字段；id 由系统根据名称自动生成。sceneId / chapterId / linkedItemId 等引用字段请填对应名称，不要填机器 id。");
  lines.push("只输出一个合法 JSON 对象，不要 markdown 代码围栏，不要解释；JSON 必须完整闭合。");
  lines.push("严格去重与收敛：");
  lines.push("- 只有原文出现明确的『场景 N: / 第 N 章: / 地图节点』或独立地点标题时才输出 scene；房间、走廊、楼层、事件、NPC 都不算新场景，同一分块最多 1 个新场景。");
  lines.push("- 每个分块独立处理：如果本段出现上述明确的场景 / 地点标题，structured.scenes 必须至少输出 1 条，不要因为可能与其他分块重复而省略；重复由系统统一去重。");
  lines.push("- 如果原文只提到某个文字材料的标题、页码、页眉，或只指向一张图片而没有正文，不要生成空的 / 占位的 clue，交给图片分析分支处理。");
  lines.push("- 如果原文出现 # / ## 级章节标题或明确章节名，必须放入 structured.chapters；chapter 与 scene 可以同时存在，不要因为输出了 scene 就省略 chapters。");
  lines.push("- clues 只提取会影响调查推进、提供新信息或可交给玩家的内容；每个分块最多 2 条；普通背景、氛围描述、NPC 生平请归入 sections，不要单独列为 clue。");
  lines.push("- 同一实体的不同称呼 / 化名统一放进 aliases；name / title 用原文最正式的名称，不要按称呼拆成多条。");
  lines.push("- items 只提取可携带 / 可使用的实体道具、书籍、武器、神器；文字材料、线索、档案、笔记本身请放入 clues，不要放入 items。");
  lines.push("- magic 只提取原文明确写出的法术 / 咒文；同一法术的不同译名请合并为一条。");

  lines.push("- NPC 的 skills 必须使用规则包技能 ID，不要输出中文技能名或描述性技能名。常用 ID：FIGHTING_BRAWL(格斗/斗殴/肉搏/爪/牙/撕咬)、DODGE(闪避)、FIREARMS_HANDGUN(手枪)、FIREARMS_RIFLE(步枪/霰弹枪)、FIREARMS_BOW(弓)、THROW(投掷)、CLIMB(攀爬)、STEALTH(潜行)、LISTEN(聆听)、SPOT_HIDDEN(侦查)、SLEIGHT_OF_HAND(妙手)、LIBRARY_USE(图书馆使用)、OCCULT(神秘学)、CTHULHU_MYTHOS(克苏鲁神话)、LAW(法律)、FIRST_AID(急救)、PSYCHOLOGY(心理学)、CHARM(魅惑)、FAST_TALK(话术)、INTIMIDATE(恐吓)、PERSUADE(说服)、CREDIT_RATING(信用评级)。技能条目格式：{\"skill\":\"FIGHTING_BRAWL\",\"value\":40}。");
  lines.push("- NPC 的 weapons 必须可结算：{\"name\":\"武器或攻击名\",\"damage\":\"1d3+db 或 1d6 等纯骰式\",\"range\":\"MELEE / NEAR / FAR\",\"skillId\":\"FIGHTING_BRAWL\",\"attacks\":1,\"notes\":\"\"}；不要写中文伤害描述，没有武器就省略。");
  lines.push("- 法术 effects 必须是可执行对象数组，不要写字符串。可用 type：DAMAGE(amount 骰式)、HEAL(amount 骰式)、MP_RESTORE(amount 数字)、MP_DRAIN(amount 数字)、SAN_LOSS(amount 骰式)、SAN_RESTORE(amount 数字)、STATUS(key,stacks)、ARMOR(amount 骰式,durationTicks=0)、SUMMON(name,count,durationTicks=0)、DOT(amount 骰式,durationTicks)、STUN(durationActions)、CONTROL(durationActions)、CLEANSE(keys)。mpCost 必须是数字或公式字符串；sanCost 必须是骰式或数字；没有直接战斗效果的法术 effects 可以为空，不要编造。");
  lines.push("- 给护甲 / 防护物理伤害的法术写 ARMOR，不要写成 DAMAGE；召唤类法术写 SUMMON，name 填召唤物名，count 填数量；召唤物会优先匹配房间内独立 NPC 卡。");
  lines.push("- 如果原文明确写出结局 / 奖励 / SAN 成长 / 技能成长 / 酬金等，必须放入对应字段，不要遗漏。");
  lines.push("尽量短：sections 只写一句话摘要，structured 每个数组最多 2 条，description 压缩到一句话。");
  if (opts && opts.retry) {
    lines.push("这是截断/失败后的重试，请进一步压缩：只保留最重要的 1-3 条记录，总长度控制在 800 个中文字符以内，并务必闭合 JSON。");
  }
  return lines;
}

function agentUserPrompt(route, chunk, hints, opts) {
  const lines = agentCommonRequirements(route, hints, opts);
  lines.push("来源：" + String(chunk.filename || "素材") + "，本文件第 " + String(chunk.fileIndex || 1) + "/" + String(chunk.fileTotal || 1) + " 段" + (chunk.heading ? "，最近标题：" + chunk.heading : ""));
  if (opts && opts.splitIndex !== undefined && opts.splitTotal !== undefined) {
    lines.push("这是原失败片段的第 " + String(opts.splitIndex + 1) + "/" + String(opts.splitTotal) + " 部分，只提取本部分内容。");
  }
  lines.push("只允许输出以下结构（示例值只是格式说明，不是素材内容；不要输出 id 字段）：");
  lines.push(schemaHintForRoute(route));
  lines.push("");
  lines.push("本段原文：");
  lines.push(String(chunk.text || ""));
  return lines.join("\n");
}

function buildAgentMessages(route, chunk, hints, opts) {
  return [
    { role: "system", content: agentSystemPrompt(route, hints, opts) },
    { role: "user", content: agentUserPrompt(route, chunk, hints, opts) }
  ];
}

function buildVisionMessages(batch, hints) {
  const lines = [];
  lines.push("你是图片视觉分析 Agent（分支身份：" + routeLabel("image") + "）。");
  lines.push("目标系统：" + hints.system + "；年代：" + hints.era + "。");
  lines.push("请逐张分析下面的图片素材，并把结果整理成单个合法 JSON 对象：{\"images\":[...]}。");
  lines.push("每张图片必须返回一条 images 记录，filename 与输入完全一致。");
  lines.push("kind 只能是 MAP / SCENE / HANDOUT / CLUE / NPC / ITEM / TEXT / OTHER 之一。");
  lines.push("transcription 逐字抄录图中可见文字（最多 2000 字）；description 只客观描述画面，不要脑补。");
  lines.push("section 选一个标准章节；sectionText 可直接写进该章节的中文正文，最多 1200 字。");
  lines.push("如果是地图尽量给出 scene；是手书/文件给 clue；是人物立绘给 npc；是物品给 item；否则对应字段返回 null。");
  lines.push("只返回单个合法 JSON 对象，不要解释、不要 markdown 代码围栏，数组最多 " + String(batch.length) + " 条。");
  lines.push("");
  lines.push("图片清单：");
  for (const image of batch) {
    lines.push("- filename：" + String(image.filename || "") + "；引用路径：" + String(image.relativePath || ""));
    if (image.pageNumber !== undefined && image.pageNumber !== null) {
      lines.push("  来源：PDF 第 " + String(image.pageNumber) + " 页" + (image.origin === "PAGE_RENDER" ? "（整页渲染）" : "（内嵌图）"));
    }
    if (image.pageText !== undefined && String(image.pageText).trim().length > 0) {
      lines.push("  同页文字（可能不完整）：" + String(image.pageText).trim().slice(0, 1200));
    }
  }
  const userContent = [{ type: "text", text: lines.join("\n") }];
  for (const image of batch) {
    if (image && typeof image.dataUrl === "string" && image.dataUrl.length > 0) {
      userContent.push({ type: "image_url", image_url: { url: image.dataUrl } });
    }
  }
  return [
    { role: "system", content: "你是 TRPG 素材视觉分析助手。每次调用都是独立任务，只依据当前图片与随图文字输出严格 JSON；看不清或不确定的内容必须如实说明，不得脑补。" },
    { role: "user", content: userContent }
  ];
}

function validatorSystemPrompt() {
  return [
    "你是严格的 JSON 格式校验与修复 Agent。",
    "你的唯一职责是把用户提供的模型原始输出修复为单个合法 JSON 对象。",
    "禁止新增、删除或编造事实；只允许调整格式、补齐括号、去掉解释文字、合并重复顶层对象、丢弃不完整字段。",
    "输出必须是可直接 JSON.parse 的单个对象，不要 markdown，不要解释。",
    "不要输出 id 字段；id 由系统根据名称自动生成。"
  ].join("");
}

function validatorUserPrompt(rawContent, route, label) {
  const lines = [];
  lines.push("来源标签：" + String(label || "未命名"));
  lines.push("原始分支：" + routeLabel(route));
  lines.push("期望字段形状（只作为校验参考，不要照抄示例值）：");
  lines.push(schemaHintForRoute(route));
  lines.push("要求：");
  lines.push("1) 如果原文里有多个 JSON 对象，选择字段最完整的一个，不要拼接无关内容。");
  lines.push("2) 如果 JSON 被截断，只保留已经完整闭合的字段，丢弃未完成部分，输出合法 JSON。");
  lines.push("3) 如果原文夹杂解释文字，删除解释文字，只保留 JSON。");
  lines.push("4) 不要新增原文没有的事实，不要输出 id。");
  lines.push("");
  lines.push("原始输出：");
  lines.push(String(rawContent || ""));
  return lines.join("\n");
}

function buildValidatorMessages(rawContent, route, label) {
  return [
    { role: "system", content: validatorSystemPrompt() },
    { role: "user", content: validatorUserPrompt(rawContent, route, label) }
  ];
}

const ROUTE_KEY = "narrative";
const ROUTE_LABEL = "剧情与场景";
/**
 * 分支「构建请求」节点通用代码。
 * build-workflows.mjs 会注入 ROUTE_KEY / ROUTE_LABEL。
 */

const requests = [];

for (let index = 0; index < items.length; index += 1) {
  const input = (items[index] && items[index].json) ? items[index].json : {};
  const ctx = (input.context && typeof input.context === "object") ? input.context : {};
  const hints = ctx.hints && typeof ctx.hints === "object"
    ? ctx.hints
    : { system: "COC7", era: "MODERN", instructions: "" };
  const isImage = ROUTE_KEY === "image" || input.kind === "image";
  const messages = isImage
    ? buildVisionMessages(Array.isArray(input.imageBatch) ? input.imageBatch : [], hints)
    : buildAgentMessages(ROUTE_KEY, input.chunk || {}, hints, {});
  const body = {
    model: isImage ? (ctx.visionModel || ctx.model || "deepseek-flash") : (ctx.model || "deepseek-flash"),
    temperature: 0.0,
    max_tokens: ctx.maxTokens || 8192,
    stream: false,
    response_format: { type: "json_object" },
    messages
  };
  const originId = String(input.originId || (ROUTE_KEY + "-" + String(index + 1)));
  const requestId = "req-" + originId;
  const baseUrl = String(ctx.deepseekBaseUrl || "https://api.deepseek.com").replace(/\/+$/, "");
  requests.push({
    json: {
      requestId,
      originId,
      route: ROUTE_KEY,
      kind: isImage ? "image" : "chunk",
      label: input.label || (ROUTE_LABEL + " " + String(index + 1)),
      chunk: input.chunk || null,
      imageBatch: Array.isArray(input.imageBatch) ? input.imageBatch : [],
      chunkGroupId: input.chunkGroupId || "",
      context: ctx,
      fallbackText: !isImage && input.chunk && typeof input.chunk.text === "string" ? input.chunk.text.slice(0, 4000) : "",
      url: baseUrl + "/chat/completions",
      body
    }
  });
}

return requests;

