  let output = "";
  let inString = false;
  let escaped = false;
  for (let index = 0; index < text.length; index += 1) {
    const char = text[index];
    if (inString) {
      if (escaped) {
        output += char;
        escaped = false;
        continue;
      }
      if (char === "\\") {
        output += char;
        escaped = true;
        continue;
      }
      if (char === '"') {
        let lookahead = index + 1;
        while (lookahead < text.length && /\s/.test(text[lookahead])) lookahead += 1;
        const next = text[lookahead];
        const isClosing = next === undefined || next === "," || next === "}" || next === "]" || next === ":";
        if (isClosing) {
          output += char;
          inString = false;
        } else {
          output += '\\"';
        }
        continue;
      }
      if (char === "\n") {
        output += "\\n";
        continue;
      }
      if (char === "\r") {
        output += "\\r";
        continue;
      }
      if (char === "\t") {
        output += "\\t";
        continue;
      }
      output += char;
      continue;
    }
    if (char === '"') {
      inString = true;
      output += char;
      continue;
    }
    output += char;
  }
  return output.replace(/,\s*([}\]])/g, "$1");
}

function collectBalancedJsonObjects(text, limit) {
  const value = String(text || "");
  const results = [];
  const max = Math.min(value.length, 300000);
  let starts = 0;
  for (let index = 0; index < max && starts < limit; index += 1) {
    if (value[index] !== "{") continue;
    starts += 1;
    let depth = 0;
    let inString = false;
    let escaped = false;
    let end = -1;
    for (let cursor = index; cursor < max; cursor += 1) {
      const char = value[cursor];
      if (inString) {
        if (escaped) {
          escaped = false;
          continue;
        }
        if (char === "\\") {
          escaped = true;
          continue;
        }
        if (char === '"') inString = false;
        continue;
      }
      if (char === '"') {
        inString = true;
        continue;
      }
      if (char === "{") depth += 1;
      else if (char === "}") {
        depth -= 1;
        if (depth === 0) {
          end = cursor;
          break;
        }
      }
    }
    if (end > index) results.push(value.slice(index, end + 1));
  }
  return results;
}

function tryParseJsonCandidate(candidate) {
  const text = String(candidate || "").trim();
  if (text.length === 0) return null;

  if (typeof jsonrepairLib === "function") {
    try {
      const parsed = JSON.parse(jsonrepairLib(text));
      if (parsed !== null && typeof parsed === "object" && Array.isArray(parsed) === false) return parsed;
    } catch (error) {
      // ignore
    }
  }

  try {
    const parsed = JSON.parse(text);
    if (parsed !== null && typeof parsed === "object" && Array.isArray(parsed) === false) return parsed;
  } catch (error) {
    // ignore
  }

  const repaired = repairJsonText(text);
  if (repaired !== text) {
    try {
      const parsed = JSON.parse(repaired);
      if (parsed !== null && typeof parsed === "object" && Array.isArray(parsed) === false) return parsed;
    } catch (error) {
      // ignore
    }
  }

  return null;
}

function scoreParsedObject(parsed, candidate, original) {
  if (parsed === null || typeof parsed !== "object" || Array.isArray(parsed)) return -1;
  const keys = Object.keys(parsed);
  if (keys.length === 0) return 1;
  let score = Math.min(30, keys.length);
  if (parsed.meta && typeof parsed.meta === "object") score += 30;
  if (parsed.sections && typeof parsed.sections === "object") score += 25;
  if (parsed.structured && typeof parsed.structured === "object") score += 35;
  if (Array.isArray(parsed.images)) score += 30;
  if (parsed.chapters || parsed.scenes || parsed.npcs || parsed.clues || parsed.items || parsed.magic || parsed.encounters) score += 12;
  score += Math.min(20, String(candidate || "").length / 500);
  const position = String(original || "").indexOf(String(candidate || ""));
  if (position > 0) score += Math.min(12, position / 200);
  return score;
}

function extractJsonObject(text) {
  const trimmed = String(text || "").trim();
  const withoutFence = trimmed
    .replace(/^```(?:json)?\s*/i, "")
    .replace(/\s*```$/i, "")
    .trim();
  if (withoutFence.length === 0) return null;

  const candidates = [withoutFence];

  const entireStart = withoutFence.indexOf("{");
  const entireEnd = withoutFence.lastIndexOf("}");
  if (entireStart >= 0 && entireEnd > entireStart) {
    candidates.push(withoutFence.slice(entireStart, entireEnd + 1));
  }

  const thinkingMarker = "end▁of▁thinking";
  const markerIndex = withoutFence.lastIndexOf(thinkingMarker);
  if (markerIndex >= 0) {
    const afterMarker = withoutFence.slice(markerIndex + thinkingMarker.length).trim();
    if (afterMarker.length > 0) candidates.unshift(afterMarker);
  }

  const balanced = collectBalancedJsonObjects(withoutFence, 200);
  for (const candidate of balanced) candidates.push(candidate);

  let best = null;
  let bestScore = -1;
  for (const candidate of candidates) {
    const parsed = tryParseJsonCandidate(candidate);
    if (parsed === null) continue;
    const score = scoreParsedObject(parsed, candidate, withoutFence);
    if (score > bestScore) {
      best = parsed;
      bestScore = score;
    }
  }
  return best;
}

/**
 * 多 Agent 提示词与角色定义（按内容类型路由版本）。
 *
 * 这个文件会被 build-workflows.mjs 内联进：
 * - 分类与分块（生成 route 标记）
 * - 各分支的「构建请求」Code 节点
 * - 各分支的「解析结果」Code 节点
 *
 * 重要：不要在 schema 示例里要求模型输出 id；id 统一由聚合节点根据实体名生成，
 * 避免多个分块都输出 npc1 / scene1 导致应用侧按 id 合并时串实体。
 */

const STANDARD_SECTIONS = [
  "元信息", "真相与背景", "剧情梗概", "开场钩子", "关键NPC", "地点与场景",
  "线索", "遭遇与战斗", "道具与手书", "怪物与神话生物", "结局分支",
  "奖励与成长", "KP备注", "附录"
];

function routeLabel(route) {
  const labels = {
    narrative: "剧情与场景",
    npc: "NPC 与规则道具",
    notes: "设定笔记",
    handout: "线索与手书",
    setting: "设定与规则",
    image: "图片与地图",
    general: "综合提取",
    noop: "无需校验"
  };
  return labels[route] || String(route || "未知分支");
}

function sectionSchema() {
  const parts = [];
  for (const name of STANDARD_SECTIONS) parts.push("\"" + name + "\":\"...\"");
  return "{" + parts.join(",") + "}";
}

function imageSchemaHint() {
  return "{\"images\":[{\"filename\":\"与输入完全一致\",\"kind\":\"MAP / SCENE / HANDOUT / CLUE / NPC / ITEM / TEXT / OTHER\",\"transcription\":\"图中可见文字逐字抄录，最多 2000 字\",\"description\":\"客观描述画面，不要脑补\",\"section\":\"标准章节名\",\"sectionText\":\"可直接写入章节的中文正文，最多 1200 字\",\"scene\":null,\"clue\":null,\"npc\":null,\"item\":null}]}";
}

function npcSchema() {
  return "{\"aliases\":[],\"name\":\"NPC 名\",\"tier\":\"MINION / STANDARD / ELITE / BOSS\",\"rarity\":\"COMMON\",\"race\":null,\"tags\":[],\"description\":\"...\",\"portrait\":\"\",\"statText\":\"原文属性行 / 数值块逐字复制\",\"attributes\":{\"str\":50,\"con\":50,\"siz\":50,\"dex\":50,\"app\":50,\"int\":50,\"pow\":50,\"edu\":50,\"luck\":50},\"db\":\"1d4\",\"build\":1,\"move\":8,\"skills\":[{\"skill\":\"FIGHTING_BRAWL\",\"value\":40}],\"weapons\":[{\"name\":\"武器或攻击名\",\"damage\":\"1d3+db\",\"range\":\"MELEE\",\"skillId\":\"FIGHTING_BRAWL\",\"attacks\":1,\"notes\":\"\"}],\"maxHp\":12,\"maxMp\":10,\"maxSan\":50,\"maxDp\":0}";
}

function magicSchema() {
  return "{\"aliases\":[],\"name\":\"法术名\",\"skill\":\"OCCULT\",\"mpCost\":\"1\",\"sanCost\":\"0\",\"damage\":\"\",\"target\":\"ONE\",\"targeting\":\"ENEMY\",\"effects\":[{\"type\":\"DAMAGE\",\"amount\":\"1d6\"}],\"description\":\"...\"}";
}

function schemaHintForRoute(route) {
  if (route === "narrative") {
    return [
      "{\"meta\":{\"title\":\"...\",\"summary\":\"...\",\"background\":\"...\",\"occupationRecommendation\":\"...\"},",
