      "\"magic\":[" + magicSchema() + "],",
      "\"endings\":[{\"aliases\":[],\"name\":\"结局名\",\"condition\":\"...\",\"description\":\"...\"}],",
      "\"rewards\":[{\"aliases\":[],\"name\":\"奖励名\",\"description\":\"...\"}]",
