        });
      }
    } else {
      outputItems.push({
        json: {
          originId,
          originLabel: label,
          stage2Id: originId + ":s2:0",
          needsStage2: true,
          stage2Kind: "retry",
          route: ROUTE_KEY,
          kind,
          label: label + "（重试）",
          chunk: request.chunk || null,
          imageBatch: lightImageBatch(request.imageBatch || []),
          chunkGroupId: request.chunkGroupId || "",
          url: request.url,
          body: buildRetryBody(request, request.chunk || {}, 0, 1, kind === "image"),
          fallbackText: ""
        }
      });
    }
    continue;
  }

  const parsed = extractJsonObject(rawContent);
  if (parsed !== null) {
    outputItems.push({
      json: {
        originId,
        originLabel: label,
        stage2Id: originId + ":accepted",
        needsStage2: false,
        stage2Kind: null,
        route: ROUTE_KEY,
        kind,
        label,
        parsed,
        chunk: request.chunk || null,
        imageBatch: lightImageBatch(request.imageBatch || []),
        chunkGroupId: request.chunkGroupId || "",
        fallbackText: kind === "chunk" && request.chunk ? capText(request.chunk.text, 4000) : ""
      }
    });
    continue;
  }

  outputItems.push({
    json: {
      originId,
      originLabel: label,
      stage2Id: originId + ":validate",
      needsStage2: true,
      stage2Kind: "validate",
      route: ROUTE_KEY,
      kind,
      label,
      chunk: request.chunk || null,
      imageBatch: lightImageBatch(request.imageBatch || []),
      chunkGroupId: request.chunkGroupId || "",
      url: request.url,
      body: buildValidatorBody(request, rawContent),
      fallbackText: kind === "chunk" && request.chunk ? capText(request.chunk.text, 4000) : ""
    }
  });
}

return outputItems;

/**
 * 汇总所有分支解析结果，只把需要格式校验或截断重试的条目送去第二阶段。
 * 如果没有待处理条目，输出一个本地 noop 请求，保证下游聚合节点仍会执行。
 */

const pending = items.filter((item) => item && item.json && item.json.needsStage2 === true);
if (pending.length > 0) return pending;

return [{
  json: {
    originId: "noop",
    originLabel: "无需校验",
    stage2Id: "noop",
    stage2Kind: "noop",
    needsStage2: true,
    route: "noop",
    kind: "noop",
    label: "无需校验",
    url: "http://127.0.0.1:5678/healthz",
    body: { ping: true }
  }
}];

